/* DeepDive complete Spanish layer (v21).
   Translates any remaining English UI text, generated commentary, attributes and dialogs when
   the interface language is Spanish, and restores the English originals when switching back.
   Scripture text (search snippets) is left untouched. */
(function(){
'use strict';
const D={"Faith in the Book of Mormon is active trust in God, not certainty about every outcome. Alma compares the word to a seed: its growth is recognized through patient experimentation, nourishment, and experience.": "La fe en el Libro de Mormón es confianza activa en Dios, no certeza sobre cada resultado. Alma la compara con una semilla que crece mediante la paciencia y el cuidado.", "Compare Alma 32 with Ether 12:6: faith can precede a witness, but that does not make every impression infallible.": "Compara Alma 32 con Éter 12:6: la fe puede preceder al testimonio, pero eso no significa que toda impresión sea infalible.", "The record centers Jesus Christ as Redeemer, teacher, and resurrected Lord. His ministry in 3 Nephi invites people to approach Him personally, while Alma 7 emphasizes His understanding of human suffering.": "Jesucristo ocupa el centro del relato como Redentor, Maestro y Señor resucitado. En 3 Nefi invita a las personas a acercarse a Él; Alma 7 destaca que comprende el sufrimiento humano.", "Read 3 Nephi 11 alongside Mosiah 3 to compare the risen Christ's invitation with prophetic anticipation of His ministry.": "Compara 3 Nefi 11 con Mosíah 3 para explorar la invitación del Cristo resucitado y las profecías sobre Su ministerio.", "Grace is God's enabling and redeeming gift through Christ. The passages connect reconciliation, repentance, and transformation rather than treating salvation as a reward for flawless performance.": "La gracia es el don redentor y fortalecedor de Dios mediante Cristo. Estos pasajes relacionan reconciliación, arrepentimiento y transformación.", "Compare 2 Nephi 2 and Moroni 10:32–33: what does Christ do that people cannot accomplish alone?": "Compara 2 Nefi 2 con Moroni 10:32–33: ¿qué hace Cristo que las personas no pueden lograr por sí solas?", "Prayer appears as personal wrestling, communal concern, gratitude, and repeated turning toward God. Enos's experience expands from his own soul to his people and even his enemies.": "La oración aparece como lucha personal, preocupación comunitaria, gratitud y acercamiento constante a Dios. Enós pasa de orar por sí mismo a orar por otras personas.", "Alma 34 asks readers to carry prayer into ordinary responsibilities, including concern for others.": "Alma 34 lleva la oración a la vida cotidiana y a nuestra responsabilidad por los demás.", "The Holy Ghost is described as a source of guidance, testimony, and spiritual knowledge. The text depicts different contexts of reception, so no single emotional sensation should be imposed on every reader.": "El Espíritu Santo es fuente de guía, testimonio y conocimiento espiritual. Los relatos muestran distintas maneras de recibirlo, sin imponer una emoción idéntica a todos.", "Compare 2 Nephi 32:5 with Moroni 10:4–5 and the people's response in 3 Nephi 11.": "Compara 2 Nefi 32:5, Moroni 10:4–5 y la respuesta del pueblo en 3 Nefi 11.", "Covenants connect belonging to Christ with ongoing responsibilities toward God and neighbors. At the waters of Mormon, baptismal commitments include bearing burdens and comforting mourners.": "Los convenios unen la pertenencia a Cristo con responsabilidades hacia Dios y el prójimo. En las aguas de Mormón, el bautismo incluye llevar cargas y consolar a quienes lloran.", "Read Mosiah 18:8–10 as a description of community, not merely an individual ceremony.": "Lee Mosíah 18:8–10 como una descripción de comunidad, no solo de una ceremonia individual.", "Repentance is a turning toward God that can involve sorrow, changed desires, restitution, and new life. Alma 36 depicts remembered pain giving way to joy through Christ.": "El arrepentimiento es volverse hacia Dios mediante el cambio de deseos y acciones. Alma 36 describe cómo el recuerdo doloroso da paso al gozo en Cristo.", "Compare Alma 36 and 3 Nephi 9:20–22 to distinguish transformation from shame alone.": "Compara Alma 36 y 3 Nefi 9:20–22 para distinguir transformación de mera vergüenza.", "Forgiveness involves God's mercy and the demanding work of responding to those who have harmed us. Nephi's response to his brothers offers a narrative case, while 3 Nephi teaches forgiveness directly.": "El perdón incluye la misericordia de Dios y el difícil trabajo de responder al daño. La respuesta de Nefi a sus hermanos ofrece un ejemplo narrativo.", "Forgiveness need not mean denying harm or abandoning wise boundaries.": "Perdonar no exige negar el daño ni abandonar límites prudentes.", "Charity is more than kindness in feeling: it appears in material care, refusal to judge the needy, and the rejection of social divisions. Moroni 7 describes charity's character and its relationship to Christ.": "La caridad es más que un sentimiento: incluye ayuda material, no juzgar a los necesitados y rechazar divisiones sociales. Moroni 7 describe su relación con Cristo.", "Compare Mosiah 4:16–19 and 4 Nephi 1:15–17: how does love reshape a community?": "Compara Mosíah 4:16–19 y 4 Nefi 1:15–17: ¿cómo transforma el amor a una comunidad?", "Moral agency entails meaningful choice and responsibility. Lehi's teaching about freedom and captivity places choice in the context of Christ's redemption.": "El albedrío moral implica elecciones significativas y responsabilidad. Lehi sitúa la libertad humana en el contexto de la redención de Cristo.", "Ask how agency interacts with circumstance, coercion, and the responsibilities of communities.": "Considera cómo interactúa el albedrío con las circunstancias, la coerción y las obligaciones comunitarias.", "Alma 42 wrestles with accountability and compassion together. The chapter does not portray mercy as indifference to harm or justice as the absence of hope.": "Alma 42 examina conjuntamente la responsabilidad y la compasión. La misericordia no equivale a indiferencia ante el daño.", "Track how repentance, restoration, and Christ's atonement shape the argument.": "Observa cómo el arrepentimiento, la restauración y la Expiación forman parte del argumento.", "Revelation in the record includes visions, spiritual prompting, learning over time, and testimony gained through seeking. Nephi's desire to know for himself stands alongside Alma's account of prayer and fasting.": "La revelación incluye visiones, impresiones espirituales, aprendizaje gradual y testimonio. Nefi desea conocer por sí mismo; Alma describe oración y ayuno.", "Compare different narrators before assuming revelation always arrives in one recognizable form.": "Compara distintos narradores antes de suponer que toda revelación llega de una sola manera.", "Covenant identity is portrayed as a relationship that changes conduct and belonging. Mosiah 5 emphasizes taking Christ's name, while Alma 5 asks whether an inner change has occurred.": "La identidad del convenio es una relación que transforma la conducta y el sentido de pertenencia. Mosíah 5 habla de tomar el nombre de Cristo.", "Explore how identity can be both received as a gift and expressed through choices.": "Explora cómo la identidad puede recibirse como don y expresarse mediante decisiones.", "Women's voices are comparatively sparse in the surviving narrative, making their appearances especially important to read carefully. Sariah's worry and testimony, Abish's action, and the mothers of Helaman's soldiers show distinct forms of faith and agency.": "Las voces de las mujeres son relativamente escasas en el relato conservado. Saríah, Abish y las madres de los jóvenes soldados muestran formas distintas de fe y acción.", "Notice both what the text says and whose experiences the narrator leaves unrecorded.": "Presta atención tanto a lo que se cuenta como a las experiencias que el narrador no registra.", "The record repeatedly tests leadership against service, humility, and accountability. King Benjamin's labor among his people contrasts with examples of power used for personal advantage.": "El relato evalúa el liderazgo mediante el servicio, la humildad y la responsabilidad. Benjamín trabaja entre su pueblo, en contraste con el poder usado para beneficio propio.", "Ask whether a leader's actions relieve burdens or increase them.": "Pregunta si las acciones de un líder alivian o aumentan las cargas ajenas.", "War narratives present defense, loss, and difficult moral choices, while 4 Nephi depicts a society without contention rooted in love. Military success is not the same as the full scriptural vision of peace.": "Los relatos bélicos presentan defensa, pérdidas y decisiones difíciles; 4 Nefi muestra una sociedad sin contención, basada en el amor.", "Compare Alma 48 with 4 Nephi: what kind of society is the ultimate goal?": "Compara Alma 48 con 4 Nefi: ¿cuál es la meta social más profunda?", "Pride is associated with hierarchy, contempt, wealth-based status, and forgetting dependence on God. Humility makes room for correction and compassion.": "El orgullo se relaciona con jerarquías, desprecio, estatus económico y olvido de Dios. La humildad abre espacio a la corrección y la compasión.", "Jacob 2:13–21 connects pride directly to economic and social relationships.": "Jacob 2:13–21 vincula el orgullo directamente con las relaciones económicas y sociales.", "Baptism marks discipleship, repentance, and covenant participation. Mosiah 18 frames it through concrete promises to support other people, and 3 Nephi 11 centers Christ's authority and teaching.": "El bautismo marca el discipulado, el arrepentimiento y la participación en convenios. Mosíah 18 lo presenta como una promesa concreta de ayudar a otras personas.", "Consider how baptism changes obligations toward neighbors, not just private beliefs.": "Considera cómo el bautismo transforma nuestras obligaciones hacia el prójimo.", "The resurrection is presented as a universal restoration made possible by Christ. Alma 40 and 2 Nephi 9 explain its significance, while 3 Nephi 11 narrates witnesses encountering the risen Savior.": "La resurrección se presenta como una restauración universal posible por Cristo. Alma 40 y 2 Nefi 9 explican su significado.", "Distinguish the scriptural promise of resurrection from speculation about its mechanics.": "Distingue la promesa de la resurrección de las especulaciones sobre sus mecanismos.", "Family relationships in the record include love, conflict, teaching, grief, and hope. Lehi's longing for his children and the testimony of the stripling warriors' mothers show both tenderness and complexity.": "Las familias del relato viven amor, conflicto, enseñanza, duelo y esperanza. El deseo de Lehi por sus hijos y el testimonio de las madres muestran ternura y complejidad.", "Avoid assuming every family experience in the text is a simple model for modern families.": "No supongas que cada experiencia familiar narrada es un modelo sencillo para las familias actuales.", "A spiritual idiolect is a modern metaphor for the personally distinctive ways individuals may recognize, describe, and respond to divine communication. Nephi speaks of a softened heart, Enos of extended prayer, Alma of knowledge developed through fasting and prayer, and 3 Nephi of a voice people learn to hear.": "Un idiolecto espiritual es una metáfora moderna para las formas personales de reconocer, describir y responder a la comunicación divina. Nefi habla de un corazón ablandado; Enós, de oración prolongada; Alma, de ayuno y oración.", "This is an interpretive framework, not an explicit Book of Mormon doctrine. Compare similarities without erasing differences or assuming that one person's experience must become everyone's pattern.": "Es un enfoque interpretativo, no una doctrina explícita del Libro de Mormón. Compara semejanzas sin borrar diferencias ni imponer la experiencia de una persona a todos.", "This interpretive theme asks how divine grace can work through incomplete, vulnerable people. Ether 12:27 connects weakness, humility, and strength; Nephi's lament in 2 Nephi 4 shows devotion alongside distress; Alma 36 describes radical change through Christ.": "Este enfoque pregunta cómo la gracia divina actúa en personas vulnerables e incompletas. Éter 12:27 relaciona debilidad, humildad y fortaleza; 2 Nefi 4 muestra la angustia de Nefi.", "The text does not require us to call abuse, injustice, or every failure divinely intended. The beauty lies in God's capacity to heal and transform, not in glorifying harm.": "El texto no exige llamar divinamente previstos al abuso, la injusticia o cada error. La belleza está en la capacidad de Dios para sanar y transformar, no en glorificar el daño.", "Care for people in material need is a recurring obligation, not a peripheral act of generosity. King Benjamin teaches that possessions ultimately depend on God and rejects withholding aid by judging the poor; Alma 1 describes a community sharing with those in need.": "Cuidar a quienes tienen necesidades materiales es una obligación recurrente. Benjamín rechaza negar ayuda por juzgar a los pobres; Alma 1 describe una comunidad que comparte recursos.", "Compare individual generosity with community arrangements that reduce deprivation. What changes when help is treated as covenant responsibility rather than optional charity?": "Compara la generosidad individual con prácticas comunitarias que reducen la privación. ¿Qué cambia cuando la ayuda es responsabilidad del convenio?", "The Book of Mormon criticizes communities that accumulate wealth while disregarding vulnerable neighbors. Jacob condemns status based on riches, and Mormon 8 rebukes costly adornment amid suffering.": "El Libro de Mormón critica a las comunidades que acumulan riqueza mientras ignoran a los vulnerables. Jacob condena el estatus basado en las riquezas y Mormón 8 reprende el lujo ante el sufrimiento.", "Study both actions and omissions: what excuses allow people to overlook suffering, and what does the text ask them to change?": "Estudia acciones y omisiones: ¿qué excusas permiten ignorar el sufrimiento y qué cambios pide el texto?", "The record contains both universalist declarations and troubling descriptions of inherited group divisions. 2 Nephi 26:33 affirms that all are alike unto God, while passages about Nephites and Lamanites require careful historical, literary, and ethical reading.": "El relato contiene declaraciones de inclusión universal y descripciones problemáticas de divisiones heredadas. 2 Nefi 26:33 afirma que todos son iguales ante Dios.", "Distinguish a narrator's portrayal from God's moral ideal. Do not treat references to skin or lineage as scientific facts or as justification for racial hierarchy; compare Jacob 3 and 4 Nephi's rejection of divisions.": "Distingue la perspectiva de un narrador del ideal moral divino. No uses referencias a piel o linaje para justificar jerarquías raciales; compara Jacob 3 y 4 Nefi.", "Economic equality in the Book of Mormon is closely tied to sharing resources, resisting status hierarchies, and preventing poverty. 4 Nephi describes a community without rich and poor, while Mosiah 4 and Alma 1 emphasize concrete care and mutual responsibility.": "La igualdad económica se vincula con compartir recursos, resistir jerarquías de estatus y evitar la pobreza. 4 Nefi describe una comunidad sin ricos ni pobres.", "The text does not supply a complete modern economic policy. Explore the moral principles and compare how different communities distribute resources and dignity.": "El texto no presenta una política económica moderna completa. Explora los principios morales y la distribución de recursos y dignidad.", "Benjamin commands practical help for the poor, rejects blaming those who ask, and counsels generosity tempered by wisdom.": "Benjamín manda ayudar a los pobres, rechaza culpar a quienes piden ayuda y aconseja generosidad sabia.", "The community shares possessions and goods so that no one is rich or poor.": "La comunidad comparte sus bienes, de modo que no hay ricos ni pobres.", "Nephi declares that all are alike unto God and all are invited to come to Christ.": "Nefi declara que todos son iguales ante Dios y están invitados a venir a Cristo.", "Jacob challenges Nephite prejudice by praising the faithfulness of Lamanite families and rebuking his own people.": "Jacob cuestiona los prejuicios nefitas y elogia la fidelidad familiar de los lamanitas.", "Moroni condemns love of wealth and fine clothing while the poor and needy suffer.": "Moroni condena el amor a las riquezas y a la ropa costosa mientras sufren los necesitados.", "The Lord tells Moroni that weakness can foster humility and that grace can make weak things strong.": "El Señor enseña a Moroni que la debilidad puede fomentar la humildad y que la gracia puede fortalecer a las personas.", "The people hear a quiet voice repeatedly before understanding and looking toward its source.": "El pueblo oye una voz suave varias veces antes de comprenderla y mirar hacia su origen.", "Alma describes gaining testimony through fasting, prayer, and revelation.": "Alma explica que obtuvo su testimonio mediante el ayuno, la oración y la revelación.", "Enos wrestles in prayer, receives assurance of forgiveness, and turns his concern outward.": "Enós lucha en oración, recibe la seguridad del perdón y comienza a preocuparse por los demás.", "Nephi prays for understanding, experiences a softened heart, and shares what he learns with Sam.": "Nefi ora para comprender, siente que su corazón se ablanda y comparte su experiencia con Sam.", "Members share food, clothing, and resources according to need and avoid turning away the poor.": "Los creyentes comparten alimentos, ropa y recursos según las necesidades de las personas.", "Jacob teaches that riches should be sought only after seeking God and used to help others.": "Jacob enseña a buscar primero a Dios y usar las riquezas para ayudar a los demás.", "Prosperity brings pride, costly clothing, inequality, and neglect of the poor.": "La prosperidad produce orgullo, ropa costosa, desigualdad y descuido de los pobres.", "Nephi grieves over his weaknesses yet remembers God's help and chooses renewed trust.": "Nefi expresa dolor por sus debilidades, recuerda la ayuda divina y renueva su confianza.", "Alma remembers his sins, calls upon Christ, and experiences relief and joy.": "Alma recuerda sus pecados, clama a Cristo y experimenta alivio y gozo.", "Moroni invites people to come to Christ and be perfected through His grace.": "Moroni invita a venir a Cristo y ser perfeccionados mediante Su gracia.", "Christ calls those who remain to return, repent, and receive healing.": "Cristo invita a los sobrevivientes a volver, arrepentirse y recibir sanación.", "Alma teaches that Christ experiences pain, sickness, temptation, and death so He can succor His people.": "Alma enseña que Cristo experimenta dolores, enfermedades, tentaciones y muerte para socorrer a Su pueblo.", "Alma compares faith to planting and nourishing a seed, inviting readers to test the word through patient spiritual growth.": "Alma compara la fe con plantar y nutrir una semilla, invitando al crecimiento espiritual paciente.", "Moroni discusses faith, witnesses, weakness, humility, and the strengthening power of grace.": "Moroni reflexiona sobre fe, testimonios, debilidad, humildad y gracia.", "Nephi urges faith amid family conflict and later forgives his brothers.": "Nefi exhorta a tener fe en medio de conflictos familiares y luego perdona a sus hermanos.", "Mormon teaches how faith, hope, and charity shape discipleship.": "Mormón enseña cómo la fe, la esperanza y la caridad forman el discipulado.", "The people learn to hear the divine voice and encounter the resurrected Jesus.": "Cristo resucitado aparece, invita a testigos personales y enseña Su doctrina.", "King Benjamin recounts the coming Messiah, His suffering, and redemption.": "Benjamín relata la venida del Mesías, Su sufrimiento y la redención.", "Nephi teaches about Christ, the law, grace, and the purpose of his record.": "Nefi enseña sobre Cristo, la ley, la gracia y el propósito de sus escritos.", "Alma describes the Savior taking upon Himself human pains, sicknesses, and sins.": "Alma describe cómo el Salvador toma sobre Sí los dolores y pecados humanos.", "Lehi explains redemption through Christ, opposition, and human agency.": "Lehi explica la redención por Cristo, la oposición y el albedrío.", "Moroni invites prayerful inquiry and urges readers to come unto Christ.": "Moroni invita a preguntar a Dios y exhorta a venir a Cristo.", "Enos recounts an extended prayer that grows from concern for himself to concern for others.": "Enós relata una oración que pasa de su propia necesidad a la preocupación por otros.", "Amulek teaches prayer, repentance, and responsibility for people in need.": "Amulek enseña la oración, el arrepentimiento y la responsabilidad por los necesitados.", "Jesus teaches prayer, remembrance, fellowship, and care for one another.": "Jesús enseña oración, recuerdo, comunión y cuidado mutuo.", "Nephi teaches prayer, feasting upon Christ's words, and guidance from the Holy Ghost.": "Nefi enseña a orar, deleitarse en las palabras de Cristo y seguir al Espíritu Santo.", "Nephi seeks to understand his father's revelations and testifies that God reveals truth to those who seek.": "Nefi busca comprender las revelaciones de su padre y enseña que Dios revela verdad.", "Alma teaches baptism as a covenant to bear burdens, mourn, comfort, and witness of God.": "Alma presenta el bautismo como convenio de llevar cargas, llorar y consolar.", "Nephi explains Christ's baptism and the path of faith, repentance, and enduring discipleship.": "Nefi explica el bautismo de Cristo y el camino del discipulado.", "Jesus teaches covenant promises and the gathering of Israel.": "Jesús enseña promesas del convenio y el recogimiento de Israel.", "The sacrament prayer emphasizes remembrance, willingness, and the promise of the Spirit.": "La oración sacramental destaca el recuerdo, la disposición y la promesa del Espíritu.", "Alma recounts his conversion, sorrow for sin, remembrance of Christ, and resulting joy.": "Alma relata su conversión, dolor por el pecado y gozo en Cristo.", "The Lord instructs Alma about repentance, forgiveness, and the community of believers.": "El Señor instruye a Alma sobre arrepentimiento, perdón y comunidad.", "Christ calls survivors to turn to Him with broken hearts and contrite spirits.": "Cristo llama a los sobrevivientes a volverse a Él con corazón quebrantado.", "Nephi and Lehi teach remembrance of Christ as the foundation of faith.": "Nefi y Lehi enseñan a recordar a Cristo como fundamento.", "Jesus teaches prayer, forgiveness, and freedom from anxious attachment to possessions.": "Jesús enseña oración, perdón y libertad de la ansiedad por las posesiones.", "Sariah expresses concern for her sons and later rejoices at their safe return.": "Saríah expresa preocupación por sus hijos y celebra su regreso.", "King Benjamin teaches that all depend on God and must not withhold help from people in need.": "Benjamín enseña dependencia de Dios y ayuda a los necesitados.", "A post-Christ community shares resources, rejects divisions, and later declines through pride.": "Una comunidad comparte recursos, rechaza divisiones y luego decae por orgullo.", "Nephi teaches that Christ invites all people, without exclusion based on status or identity.": "Nefi enseña que Cristo invita a todos sin exclusión.", "Samuel teaches accountability, repentance, and freedom to choose.": "Samuel enseña responsabilidad, arrepentimiento y libertad de elegir.", "Alma teaches accountability, spiritual understanding, and the plan of redemption.": "Alma enseña responsabilidad, comprensión espiritual y redención.", "The Nephites respond collectively to threats and organize for protection.": "Los nefitas responden juntos a amenazas y organizan su defensa.", "Abinadi teaches Christ's redeeming work and victory over death.": "Abinadí enseña la redención de Cristo y Su victoria sobre la muerte.", "Jacob teaches about resurrection, judgment, redemption, and the dangers of pride.": "Jacob enseña resurrección, juicio, redención y peligros del orgullo.", "Nephi seeks God personally and describes his heart being softened.": "Nefi busca personalmente a Dios y describe su corazón ablandado.", "Alma asks searching questions about conversion, humility, pride, and care for others.": "Alma pregunta sobre conversión, humildad, orgullo y cuidado mutuo.", "Moroni discusses revelation, faith, and the conditions of receiving further light.": "Moroni habla de revelación, fe y recepción de más luz.", "Benjamin's people make a covenant and take upon themselves Christ's name.": "El pueblo de Benjamín hace un convenio y toma el nombre de Cristo.", "Jesus teaches the Beatitudes and the ethical demands of discipleship.": "Jesús enseña las bienaventuranzas y la ética del discipulado.", "Abish acts in faith during a remarkable spiritual experience in Lamoni's household.": "Abish actúa con fe durante una experiencia espiritual en la casa de Lamoni.", "Helaman recounts the courage of young soldiers and their trust in what their mothers taught.": "Helamán relata el valor de los jóvenes soldados y la enseñanza de sus madres.", "King Benjamin connects service to others with service to God.": "Benjamín relaciona servir a otros con servir a Dios.", "The sons of Mosiah prepare to teach through patience, service, and love.": "Los hijos de Mosíah se preparan para enseñar con servicio y paciencia.", "The Jaredite journey ends in a new land, where questions of leadership and kingship arise.": "Los jareditas llegan a una nueva tierra y consideran el liderazgo.", "Mosiah discusses kingship, accountability, and the establishment of judges.": "Mosíah reflexiona sobre reyes, responsabilidad y jueces.", "The Nephites prepare to defend families, liberty, and religious freedom.": "Los nefitas se preparan para defender familias, libertad y religión.", "Moroni is described as a defender who does not delight in bloodshed.": "Moroni es presentado como defensor que no se deleita en derramar sangre.", "Jacob rebukes pride in riches and calls people to seek God and help the needy.": "Jacob reprende el orgullo por las riquezas y llama a ayudar a los pobres.", "Mormon reflects on human forgetfulness and the dangers of prosperity.": "Mormón reflexiona sobre el olvido humano y los peligros de la prosperidad.", "Moroni describes baptismal preparation and communal spiritual care.": "Moroni describe preparación bautismal y cuidado espiritual comunitario.", "Alma teaches resurrection and the state of the soul after death.": "Alma enseña la resurrección y el estado del alma después de la muerte.", "Abinadi teaches the resurrection and redemption through Christ.": "Abinadí enseña resurrección y redención por Cristo.", "Lehi's dream depicts the tree of life, his family's choices, and the iron rod.": "El sueño de Lehi presenta el árbol de la vida, decisiones familiares y barra de hierro.", "The faithful share with the poor while resisting priestcraft and inequality.": "Los fieles comparten con los pobres y resisten la desigualdad.", "Jacob rebukes Nephite behavior and challenges contempt toward Lamanite families.": "Jacob reprende a los nefitas y cuestiona su desprecio hacia familias lamanitas.", "Moroni condemns pride, wealth-centered religion, and neglect of the suffering.": "Moroni condena el orgullo, la religión centrada en riquezas y el abandono de los pobres.", "Increasing wealth and social inequality weaken the church and prompt Alma to preach.": "La riqueza y desigualdad debilitan la Iglesia y llevan a Alma a predicar.", "Ammon recalls missionary service and challenges contempt toward the Lamanites.": "Ammón recuerda su servicio y cuestiona el desprecio hacia los lamanitas.", "Nephi recounts the separation of communities; its language about skin and identity requires critical contextual reading.": "Nefi relata la separación de pueblos; el lenguaje sobre piel e identidad requiere lectura crítica.", "A command to share becomes clearer when contrasted with prophetic condemnation of indifference.": "La obligación de compartir se entiende mejor al contrastarla con la condena profética de la indiferencia.", "Practical care for neighbors helps illuminate the shared resources described in 4 Nephi.": "El cuidado práctico del prójimo ayuda a comprender los bienes compartidos de 4 Nefi.", "Mosiah 18 connects baptismal identity with bearing other people's burdens.": "Mosíah 18 relaciona el convenio bautismal con llevar las cargas de otras personas.", "Jacob and Moroni connect social neglect with wealth-based pride.": "Jacob y Moroni relacionan el abandono social con el orgullo por las riquezas.", "4 Nephi's social unity challenges both inherited divisions and material hierarchies.": "La unidad de 4 Nefi cuestiona las divisiones heredadas y las jerarquías económicas.", "Universal invitation and charity offer a moral framework for examining exclusion.": "La invitación universal y la caridad ofrecen un marco moral para examinar la exclusión.", "The community of 4 Nephi connects shared goods with the love of God.": "La comunidad de 4 Nefi relaciona los bienes compartidos con el amor de Dios.", "Different scriptural accounts describe diverse ways people seek and recognize divine guidance.": "Los relatos muestran distintas maneras de buscar y reconocer la guía divina.", "Personal accounts of divine communication can be compared with teachings about the Spirit.": "Las experiencias personales de revelación pueden compararse con las enseñanzas sobre el Espíritu.", "Individual spiritual development can include uncertainty, vulnerability, and gradual growth.": "El desarrollo espiritual individual puede incluir incertidumbre, vulnerabilidad y crecimiento gradual.", "Ether 12 and Moroni 10 connect human weakness with Christ's grace.": "Éter 12 y Moroni 10 relacionan la debilidad humana con la gracia de Cristo.", "Nephi and Alma describe inner struggle and transformation without glorifying wrongdoing.": "Nefi y Alma describen lucha interior y transformación sin glorificar las malas acciones.", "Alma's seed analogy and Nephi's seeking illuminate the relation of faith to learning.": "La semilla de Alma y la búsqueda de Nefi muestran la relación entre fe y aprendizaje.", "Christ's ministry and redeeming work provide the center of these connected teachings.": "El ministerio y la obra redentora de Cristo están en el centro de estas enseñanzas.", "Baptism is described as an entrance into obligations to God and other people.": "El bautismo inicia obligaciones hacia Dios y otras personas.", "King Benjamin's service models leadership measured by burdens relieved.": "El servicio de Benjamín muestra un liderazgo que alivia cargas.", "4 Nephi's peace points beyond the defensive conflicts of earlier narratives.": "La paz de 4 Nefi va más allá de los conflictos defensivos anteriores.", "Sariah and Abish invite attention to spiritual agency and voices often overlooked.": "Saría y Abish invitan a prestar atención a voces y acciones espirituales poco representadas.", "Accountability and compassion are explored together in Alma and the teachings of Christ.": "Alma y las enseñanzas de Cristo exploran responsabilidad y compasión juntas.", "Narratives of family conflict invite careful reflection on reconciliation and boundaries.": "Los conflictos familiares invitan a reflexionar con cuidado sobre reconciliación y límites.", "First-person testimony, family tension, visions, and the deliberate purpose of the record.": "Testimonio en primera persona, tensiones familiares, visiones y propósito deliberado del registro.", "How does Nephi's first-person narration shape our access to other people's experiences?": "¿Cómo influye la narración de Nefi en lo que sabemos de las experiencias ajenas?", "Direct moral rebuke, social concern, covenant reflection, and extended allegorical teaching.": "Reprensión moral directa, preocupación social, reflexiones sobre convenios y enseñanzas alegóricas.", "How does Jacob's criticism of his own community challenge easy insider/outsider divisions?": "¿Cómo cuestiona Jacob las divisiones entre los de dentro y los de fuera?", "Extended sermons, rhetorical questions, conversion narrative, and the seed metaphor.": "Sermones extensos, preguntas retóricas, conversión personal y la metáfora de la semilla.", "What changes when Alma teaches through questions, analogy, or autobiography?": "¿Qué cambia cuando Alma enseña mediante preguntas, analogías o autobiografía?", "Historical abridgment, moral commentary, patterns of societal rise and collapse.": "Resumen histórico, comentarios morales y patrones de ascenso y decadencia social.", "Where does the narrator interpret events rather than merely report them?": "¿Cuándo interpreta el narrador los acontecimientos en lugar de solo contarlos?", "Editorial urgency, awareness of textual weakness, invitations to future readers, and critique of wealth.": "Urgencia editorial, conciencia de sus debilidades al escribir e invitaciones a lectores futuros.", "How does Moroni's awareness of future readers shape his tone?": "¿Cómo influye en su tono la conciencia de los lectores del futuro?", "King Benjamin's obligation": "La obligación según Benjamín", "Benjamin refuses to make moral judgments a reason to deny help to those in need.": "Benjamín rechaza usar juicios morales como excusa para negar ayuda.", "Theological obligation": "Obligación teológica", "How does shared dependence on God reshape the meaning of ownership?": "¿Cómo cambia nuestra idea de propiedad al reconocer que dependemos de Dios?", "Wealth and status criticized": "Crítica a la riqueza y el estatus", "Jacob condemns pride in wealth and redirects riches toward feeding, clothing, and liberating others.": "Jacob condena el orgullo por las riquezas y pide alimentar, vestir y liberar a otros.", "Prophetic rebuke": "Reprensión profética", "What is the difference between possessing resources and using them to establish superiority?": "¿Qué diferencia hay entre poseer recursos y usarlos para sentirse superior?", "Belonging beyond prejudice": "Pertenecer sin prejuicios", "Jacob rebukes his own community and challenges its contempt for Lamanite families.": "Jacob reprende a su propio pueblo y cuestiona su desprecio por las familias lamanitas.", "Ethnic and moral critique": "Crítica étnica y moral", "How does this challenge the assumption that one's own group is automatically more righteous?": "¿Cómo cuestiona esto la idea de que nuestro grupo es automáticamente más justo?", "Community of shared goods": "Comunidad de bienes compartidos", "A community after Christ's visit shares goods and no longer has rich and poor among them.": "Después de la visita de Cristo, la comunidad comparte bienes y no hay ricos ni pobres.", "Social ideal": "Ideal social", "What practices would make such a community durable?": "¿Qué prácticas permitirían mantener una comunidad así?", "Warnings to future readers": "Advertencias a futuros lectores", "Moroni condemns lavish display and neglect of people in need.": "Moroni condena el lujo mientras las personas necesitadas sufren.", "Future-directed warning": "Advertencia futura", "Which forms of neglect can hide behind outward religious respectability?": "¿Qué formas de abandono pueden ocultarse tras la respetabilidad religiosa?", "Weakness and grace": "Debilidad y gracia", "Moroni worries about writing inadequately and receives a teaching about weakness and humility.": "Moroni teme no escribir bien y recibe una enseñanza sobre debilidad y humildad.", "Weakness can become a setting for grace; this is not a claim that every injury or injustice is intended.": "La debilidad puede ser una ocasión para la gracia; esto no significa que Dios quiera toda injusticia o daño.", "What specifically worries Moroni in the surrounding verses?": "¿Qué le preocupa específicamente a Moroni?", "Nephi's lament": "El lamento de Nefi", "Nephi admits inner conflict and grief while recalling God's past help.": "Nefi reconoce conflictos internos y recuerda la ayuda de Dios.", "Devotion and distress can coexist without making the person spiritually defective.": "La devoción y la angustia pueden coexistir.", "How does the tone change from lament to trust?": "¿Cómo cambia el tono del lamento a la confianza?", "Alma's conversion": "La conversión de Alma", "Alma remembers his wrongs, turns toward Christ, and describes an overwhelming change.": "Alma recuerda sus errores, acude a Cristo y describe una transformación.", "Transformation is possible without romanticizing the harm caused by past wrongdoing.": "La transformación es posible sin idealizar el daño de las malas decisiones.", "What makes remembrance of Christ pivotal?": "¿Por qué es decisivo recordar a Cristo?", "The suffering Savior": "El Salvador que sufre", "Alma teaches that Christ knows pains, sicknesses, temptations, and death.": "Alma enseña que Cristo conoce dolores, enfermedades, tentaciones y muerte.", "The text centers divine compassion for suffering, not the claim that all suffering was assigned as a lesson.": "El texto destaca la compasión divina, no que todo sufrimiento sea una lección asignada.", "What does it mean for divine understanding to include embodied suffering?": "¿Qué implica que Dios comprenda el sufrimiento humano?", "Invited to become": "Invitados a llegar a ser", "Growth through grace differs from demanding an impossible performance of flawlessness.": "Crecer mediante la gracia es distinto de exigir perfección inmediata.", "How does receiving grace change the meaning of becoming perfected?": "¿Cómo cambia la gracia nuestra comprensión de la perfección?", "Can personal revelation have different forms?": "¿Puede la revelación personal adoptar distintas formas?", "The narratives describe different experiences and modes of recognition. Spiritual idiolect is a modern metaphor for comparing them, not an explicit scriptural doctrine.": "Los relatos describen experiencias distintas. «Idiolecto espiritual» es una metáfora moderna, no una doctrina explícita.", "Is imperfection divinely intended?": "¿Es la imperfección una intención divina?", "The passages show grace working amid weakness and sin. They do not establish that every mistake or harmful act was intended by God.": "Los pasajes muestran gracia en medio de debilidades y pecados, pero no establecen que Dios desee todo daño.", "How should readers handle racialized language?": "¿Cómo leer el lenguaje racializado?", "Read the troubling descriptions alongside the narrative's rebukes of prejudice and its universal invitation. Avoid treating the text as scientific evidence about race.": "Compara los pasajes difíciles con las críticas a los prejuicios y la invitación universal. No los uses como prueba científica de razas.", "Does the book advocate economic equality?": "¿Promueve el libro la igualdad económica?", "The text repeatedly praises sharing and describes a community without rich and poor. It does not lay out one detailed modern economic policy.": "El texto elogia compartir y describe una comunidad sin ricos ni pobres, pero no establece una política económica moderna específica.", "How do justice and mercy coexist?": "¿Cómo conviven la justicia y la misericordia?", "Alma presents accountability and mercy as related through Christ's redemption. Compare the argument with the ethical question of repairing harm.": "Alma relaciona responsabilidad y misericordia mediante la redención de Cristo.", "A heart softened in its own way": "Un corazón ablandado a su manera", "Personal revelation": "Revelación personal", "Nephi describes a softened heart; Enos describes prolonged prayer and a change in his desires. Their accounts do not use the term “idiolect,” but invite comparison of how revelation is experienced and narrated.": "Nefi describe un corazón ablandado; Enós describe una oración prolongada y un cambio en sus deseos. Sus relatos no utilizan la palabra «idiolecto», pero permiten comparar cómo se experimenta y narra la revelación.", "What is distinctive about each person’s encounter with God?": "¿Qué distingue el encuentro de cada persona con Dios?", "What shared pattern appears beneath those differences?": "¿Qué patrón comparten esas experiencias a pesar de sus diferencias?", "A distinctive experience need not be a perfect one. Follow the next thread into human limitation.": "Una experiencia singular no tiene que ser perfecta. La siguiente conexión aborda las limitaciones humanas.", "A voice that invites attention": "Una voz que invita a prestar atención", "Spiritual language": "Lenguaje espiritual", "At Bountiful, people come to understand the voice as they listen; Alma describes knowledge obtained through fasting and prayer. Neither passage establishes a universal formula for recognizing the Spirit.": "En Abundancia, el pueblo llega a comprender la voz mientras escucha; Alma describe el conocimiento obtenido mediante el ayuno y la oración. Ninguno de los pasajes establece una fórmula universal para reconocer al Espíritu.", "What roles do attention, repetition, time, and seeking play?": "¿Qué papel desempeñan la atención, la repetición, el tiempo y la búsqueda?", "How could you respect another person’s spiritual experience without insisting it match yours?": "¿Cómo respetarías la experiencia espiritual de otra persona sin exigir que sea igual a la tuya?", "If spiritual understanding is personal and developing, what happens when the learner feels inadequate?": "Si la comprensión espiritual es personal y gradual, ¿qué ocurre cuando alguien se siente insuficiente?", "The honest voice of an imperfect disciple": "La voz sincera de un discípulo imperfecto", "Imperfection and longing": "Imperfección y anhelo", "Nephi acknowledges sorrow over his weaknesses while turning toward God. Ether links weakness with humility and the possibility of strength through grace.": "Nefi reconoce la tristeza por sus debilidades mientras se vuelve hacia Dios. Éter relaciona la debilidad con la humildad y la fortaleza que puede venir por la gracia.", "How is acknowledging weakness different from defining oneself by failure?": "¿En qué se diferencia reconocer la debilidad de definirse por el fracaso?", "Does the text say every mistake was designed by God, or that God can work through weakness?": "¿Dice el texto que Dios diseñó cada error, o que puede obrar mediante la debilidad?", "The next passage explores the difference between wrongdoing and transformative repentance.": "El siguiente pasaje explora la diferencia entre las malas acciones y el arrepentimiento transformador.", "Transformation without glorifying harm": "Transformación sin glorificar el daño", "Repentance and mercy": "Arrepentimiento y misericordia", "Alma recounts the pain of remembering his sins and the joy of turning to Christ. Alma 7 describes the Savior taking upon himself human pains, sicknesses, and infirmities.": "Alma relata el dolor de recordar sus pecados y el gozo de acudir a Cristo. Alma 7 describe al Salvador tomando sobre Sí los dolores, enfermedades y debilidades humanas.", "Which experiences in these passages are consequences, and which are gifts of healing?": "¿Qué experiencias son consecuencias y cuáles son dones de sanación?", "How can beauty emerge through grace without calling suffering itself good?": "¿Cómo puede surgir belleza mediante la gracia sin llamar bueno al sufrimiento mismo?", "Personal spiritual language may be shaped by what each person has lived through, including what Christ helps them overcome.": "El lenguaje espiritual personal puede formarse mediante las experiencias vividas, incluso aquello que Cristo nos ayuda a superar.", "Grace does not erase individuality": "La gracia no borra la individualidad", "Grace and becoming": "Gracia y transformación", "These passages invite coming unto Christ, receiving grace, and seeking guidance. Read together, they can support reflection on growth without requiring everyone to develop in the same way.": "Estos pasajes invitan a venir a Cristo, recibir gracia y buscar guía. Juntos permiten reflexionar sobre el crecimiento sin exigir que todos se desarrollen del mismo modo.", "How might grace transform someone while preserving what is unique about them?": "¿Cómo puede la gracia transformar a alguien y conservar su singularidad?", "Where do you see an invitation to act rather than an expectation of instant perfection?": "¿Dónde encuentras una invitación a actuar en vez de una exigencia de perfección inmediata?", "Bring the threads together: distinctive spiritual experiences, acknowledged weakness, and shared divine love.": "Une los temas: experiencias espirituales distintas, debilidad reconocida y amor divino compartido.", "Your own spiritual vocabulary": "Tu propio vocabulario espiritual", "Synthesis and application": "Síntesis y aplicación", "This final stop is a personal interpretive exercise, not a doctrine that God deliberately causes every imperfection. Return to the text and decide which connections it actually supports.": "Esta última etapa es un ejercicio de interpretación personal, no una doctrina que afirme que Dios causa deliberadamente toda imperfección. Vuelve al texto y evalúa qué conexiones sostiene.", "What words, images, experiences, or practices have helped you notice spiritual meaning?": "¿Qué palabras, imágenes, experiencias o prácticas te han ayudado a reconocer significado espiritual?", "How might you show compassion toward another person whose spiritual vocabulary differs from yours?": "¿Cómo mostrarías compasión hacia alguien cuyo vocabulario espiritual difiere del tuyo?", "What question would you like to follow next?": "¿Qué pregunta te gustaría explorar después?", "You can return to either topic, search the complete text, or save your reflections in the journal.": "Puedes volver a cualquiera de los temas, buscar en el texto completo o guardar tus reflexiones en el diario.", "Discipleship begins with the neighbor": "El discipulado comienza con el prójimo", "Caring for the poor": "Cuidar de los pobres", "Benjamin rejects the idea that poverty makes someone undeserving of help. Alma describes practical sharing that crosses economic lines.": "Benjamín rechaza que la pobreza haga a alguien indigno de recibir ayuda. Alma describe una comunidad que comparte recursos más allá de las diferencias económicas.", "How does Benjamin challenge the reasons people give for refusing help?": "¿Cómo cuestiona Benjamín las razones que se dan para negar ayuda?", "What practices could make compassion consistent rather than occasional?": "¿Qué prácticas convertirían la compasión en un hábito y no en una excepción?", "When care is withheld, the scriptures begin to expose the spiritual costs of neglect.": "Cuando se niega la ayuda, las escrituras revelan las consecuencias espirituales del abandono.", "When prosperity becomes neglect": "Cuando la prosperidad se convierte en abandono", "Neglecting the poor": "Desatender a los pobres", "Moroni condemns devotion to luxury while the needy suffer. Jacob teaches that material resources should serve others rather than establish status.": "Moroni condena el lujo mientras sufren los necesitados. Jacob enseña que los recursos deben servir al prójimo y no establecer superioridad.", "How does religious appearance coexist with social neglect?": "¿Cómo puede coexistir la apariencia religiosa con el abandono social?", "What changes when wealth is treated as stewardship rather than proof of superiority?": "¿Qué cambia cuando la riqueza se considera una responsabilidad y no una prueba de superioridad?", "Economic hierarchy often overlaps with group prejudice and inherited social labels.": "La jerarquía económica suele entrelazarse con prejuicios y etiquetas sociales heredadas.", "All are alike unto God": "Todos son iguales ante Dios", "Racism and prejudice": "Racismo y prejuicios", "Nephi's universal invitation stands in tension with difficult descriptions of Lamanite identity elsewhere. Jacob challenges his people's contempt. Read these passages critically without treating skin-color language as justification for racial hierarchies.": "La invitación universal de Nefi contrasta con descripciones difíciles de la identidad lamanita. Jacob cuestiona el desprecio de su pueblo. Lee estos pasajes críticamente, sin usar el lenguaje sobre el color de piel para justificar jerarquías raciales.", "Whose viewpoint shapes each description of another people?": "¿De quién es la perspectiva que configura cada descripción de otro pueblo?", "How does the declaration that all are alike unto God challenge prejudice?": "¿Cómo desafía los prejuicios la declaración de que todos son iguales ante Dios?", "A community without exclusion also confronts the economic divisions that sustain inequality.": "Una comunidad sin exclusión también enfrenta las divisiones económicas que sostienen la desigualdad.", "No rich and poor among them": "Sin ricos ni pobres entre ellos", "Economic equality": "Igualdad económica", "4 Nephi describes a community with shared goods and no class divisions. Alma 4 provides a contrasting account in which wealth and pride fracture religious life.": "4 Nefi describe bienes compartidos y ausencia de divisiones de clase. Alma 4 presenta el contraste de una comunidad religiosa fracturada por riqueza y orgullo.", "What social practices might sustain the equality described in 4 Nephi?": "¿Qué prácticas sociales podrían sostener la igualdad descrita en 4 Nefi?", "How do prosperity and inequality affect spiritual community?": "¿Cómo afectan la prosperidad y la desigualdad a la comunidad espiritual?", "The final stop asks what covenant belonging looks like in action.": "La última etapa pregunta cómo se expresa en acciones la pertenencia al convenio.", "Covenant community and the social gospel": "Comunidad del convenio y evangelio social", "Living the connection": "Vivir la conexión", "Baptismal covenants include bearing burdens and comforting others. King Benjamin identifies service to others with service to God; 4 Nephi imagines a community transformed by love.": "Los convenios bautismales incluyen llevar cargas y consolar. Benjamín identifica el servicio al prójimo con el servicio a Dios; 4 Nefi imagina una comunidad transformada por el amor.", "How might a covenant change how we use time, resources, and influence?": "¿Cómo podría un convenio cambiar el uso de nuestro tiempo, recursos e influencia?", "Which part of this study challenges your assumptions most?": "¿Qué parte de este estudio cuestiona más tus suposiciones?", "Return to any topic to pursue another thread, or save your reflections in the journal.": "Vuelve a cualquier tema para seguir otra conexión o guarda tus reflexiones en el diario.", "Home": "Inicio", "Choose a study area": "Elige un área de estudio", "A PERSONAL SCRIPTURE UNIVERSE": "TU UNIVERSO PERSONAL DE LAS ESCRITURAS", "Explore the Book of Mormon your way": "Explora el Libro de Mormón a tu manera", "Choose one way to explore. Everything else stays out of the way until you need it.": "Elige una forma de explorar. Las demás herramientas permanecerán ocultas hasta que las necesites.", "Discover": "Descubrir", "Topics, scriptures, and connections": "Temas, escrituras y conexiones", "Go deeper": "Profundizar", "Research, language, and theological labs": "Investigación, lenguaje y análisis teológico", "My study": "Mi estudio", "Paths, quizzes, and journal": "Rutas, cuestionarios y diario", "← Back to choices": "← Volver a las opciones", "Explore topics": "Explorar temas", "Search scripture": "Buscar en las escrituras", "Constellation map": "Mapa de constelaciones", "Research Studio": "Estudio de investigación", "Prophetic voices": "Voces proféticas", "Zion & social justice": "Sion y justicia social", "Imperfection & grace": "Imperfección y gracia", "Build a study path": "Crear una ruta de estudio", "Guided study paths": "Rutas de estudio guiadas", "Scripture quiz": "Cuestionario", "Study journal": "Diario de estudio", "Theme": "Tema", "Study": "Estudiar", "Language": "Idioma", "Tap a constellation to travel to another connected idea.": "Toca una constelación para explorar otra idea relacionada.", "Faith": "Fe", "Jesus Christ": "Jesucristo", "Grace and Atonement": "Gracia y Expiación", "Prayer": "Oración", "Holy Ghost": "Espíritu Santo", "Covenants": "Convenios", "Repentance": "Arrepentimiento", "Forgiveness": "Perdón", "Charity and Love": "Caridad y amor", "Agency": "Albedrío", "Justice and Mercy": "Justicia y misericordia", "Revelation": "Revelación", "Identity and Divine Potential": "Identidad y potencial divino", "Women in the Book of Mormon": "Las mujeres en el Libro de Mormón", "Leadership": "Liderazgo", "War and Peace": "Guerra y paz", "Pride and Humility": "Orgullo y humildad", "Baptism": "Bautismo", "Resurrection": "Resurrección", "Family": "Familia", "Spiritual Language & Idiolects": "Lenguaje espiritual e idiolectos", "The Divine Beauty of Imperfection": "La belleza divina de la imperfección", "Caring for the Poor": "Cuidar de los pobres", "Neglecting the Poor": "Desatender a los pobres", "Racism and Prejudice": "Racismo y prejuicios", "Economic Equality": "Igualdad económica", "What do you want to study?": "¿Qué deseas estudiar?", "Choose a topic to begin": "Elige un tema para comenzar", "Your study trail will appear here.": "Tu recorrido de estudio aparecerá aquí.", "Explore topic": "Explorar tema", "Read scripture ↗": "Leer escritura ↗", "Add to journal": "Añadir al diario", "Explore meaning ▾": "Explorar significado ▾", "Close commentary ▴": "Cerrar comentario ▴", "Topic overview": "Resumen del tema", "Deeper interpretation and connections": "Interpretación y conexiones más profundas", "Suggested passages to investigate (open the verses to read them in context):": "Pasajes sugeridos para investigar (abre los versículos para leerlos en contexto):", "Questions for deeper study": "Preguntas para profundizar", "Follow another thread": "Seguir otra conexión", "Scripture Comparison Studio": "Estudio comparativo de escrituras", "Difficult questions": "Preguntas difíciles", "Linguistic DeepDive": "Análisis lingüístico", "Phrase and motif explorer": "Explorador de frases y motivos", "Zion & Social Justice Observatory": "Observatorio de Sion y justicia social", "Theology of Imperfection Lab": "Laboratorio de la teología de la imperfección", "Search the complete Book of Mormon": "Buscar en todo el Libro de Mormón", "Search": "Buscar", "New question": "Nueva pregunta", "Save reflection": "Guardar reflexión", "Your study journal": "Tu diario de estudio", "Save reflection to journal": "Guardar reflexión en el diario", "Export journal": "Exportar diario", "Read in context": "Leer en contexto", "Narrative context": "Contexto narrativo", "Theological reflection": "Reflexión teológica", "Question to explore": "Pregunta para explorar", "Study topic": "Tema de estudio", "Interpretation lens": "Perspectiva de interpretación", "Text and narrative": "Texto y narración", "Theological": "Teológica", "Historical and cultural questions": "Preguntas históricas y culturales", "Ethical and social": "Ética y social", "Personal reflection": "Reflexión personal", "Compare passages": "Comparar pasajes", "Previous": "Anterior", "Next": "Siguiente", "My study journey": "Mi recorrido de estudio", "Connection map": "Mapa de conexiones", "My study path": "Mi ruta de estudio", "Topic challenge": "Desafío de temas", "Build my path ✦": "Crear mi ruta ✦", "Clear selection": "Borrar selección", "Follow your questions. Discover the connections. Study on your terms.": "Sigue tus preguntas. Descubre las conexiones. Estudia a tu manera.", "Pick a theme or type your own question or keyword. Suggested references are curated starting points; full-text search scans the text of your uploaded edition.": "Elige un tema o escribe tu propia pregunta. Las referencias son puntos de partida seleccionados; la búsqueda de texto completo examina la edición cargada.", "Searches extracted page text from your uploaded 2013 English edition. Results are page-level matches, not precise verse matches; consult the original PDF to verify context.": "Busca en el texto extraído de la edición inglesa de 2013. Los resultados corresponden a páginas, no necesariamente a versículos exactos; consulta el PDF original para verificar el contexto.", "Preparing offline search…": "Preparando la búsqueda sin conexión…", "One God, unique voices, unfinished people": "Un Dios, voces únicas, personas en proceso", "An interconnected six-stop study path. Move between revelation, weakness, grace, and growth. These are interpretive themes, not quotations or claims that every hardship was intended by God.": "Una ruta de seis etapas que conecta revelación, debilidad, gracia y crecimiento. Son temas interpretativos; no significan que Dios haya querido cada dificultad.", "Personal revelation & grace": "Revelación personal y gracia", "The social gospel": "El evangelio social", "Match a scripture reference to the theme it helps explore. This is a reference-recognition activity, not a test of doctrine.": "Relaciona una referencia con su tema. Es una actividad para reconocer escrituras, no un examen doctrinal.", "Select a topic and begin.": "Selecciona un tema para comenzar.", "Notes stay in this browser on this device. Export a backup before clearing browser data.": "Tus notas se guardan en este navegador y dispositivo. Exporta una copia antes de borrar los datos.", "Import journal": "Importar diario", "Independent personal study tool • Scripture links open ChurchofJesusChrist.org • Not an official Church app": "Herramienta independiente de estudio personal • Los enlaces abren ChurchofJesusChrist.org • No es una aplicación oficial de la Iglesia", "Trace theological and narrative connections between study topics. Select any node to follow another thread.": "Sigue las conexiones teológicas y narrativas entre temas. Selecciona una estrella para explorar otra idea.", "Connections are curated interpretive relationships, not claims that every passage explicitly equates the topics.": "Estas conexiones son interpretaciones seleccionadas; no implican que cada pasaje equipare explícitamente los temas.", "Start with a topic": "Comienza con un tema", "Connected ideas": "Ideas relacionadas", "Study this topic": "Estudiar este tema", "Add to my study path": "Añadir a mi ruta de estudio", "Build your own study journey": "Crea tu propio recorrido de estudio", "Choose at least two topics. DeepDive will order them by shared passages and curated connections, then create a guided sequence of readings and reflection prompts. Your selection and progress stay on this device.": "Elige al menos dos temas. DeepDive los organizará según escrituras compartidas y conexiones seleccionadas, y creará lecturas y preguntas de reflexión. Tus elecciones y avances permanecerán en este dispositivo.", "Your personalized journey is ready. The order follows documented thematic links and shared scripture contexts.": "Tu recorrido personalizado está listo. El orden sigue conexiones temáticas y contextos escriturarios compartidos.", "Select at least two topics to connect.": "Selecciona al menos dos temas para conectarlos.", "Selection cleared.": "Se borró la selección.", "Choose two or more topics and select Build my path.": "Elige dos o más temas y pulsa «Crear mi ruta».", "Read and explore": "Leer y explorar", "Reflect": "Reflexionar", "Finish path ✓": "Finalizar ruta ✓", "Next →": "Siguiente →", "Restart path": "Reiniciar ruta", "Study commentary is interpretive, not canonical scripture. Verify details in the linked passage.": "Este comentario es interpretativo, no escritura canónica. Comprueba los detalles en el pasaje enlazado.", "Investigate scripture through literary, theological, historical-contextual, ethical, and personal lenses. Distinguish textual evidence from interpretations.": "Investiga las escrituras desde perspectivas literarias, teológicas, histórico-contextuales, éticas y personales. Distingue las pruebas textuales de las interpretaciones.", "Choose two references to examine their shared themes, distinct contexts, and potential tensions.": "Elige dos referencias para examinar sus temas compartidos, contextos distintos y posibles tensiones.", "Compare the distinctive narrative presentations of Nephi, Jacob, Alma, Mormon, and Moroni. These are profiles of voices in the English scriptural text, not verified reconstructions of ancient spoken idiolects.": "Compara las voces narrativas de Nefi, Jacob, Alma, Mormón y Moroni. Son perfiles del texto inglés de las escrituras, no reconstrucciones verificadas de idiolectos antiguos.", "Follow selected recurring words and motifs to relevant passages; use the existing full-text search for exhaustive word searches.": "Explora palabras y motivos recurrentes en pasajes relacionados; usa la búsqueda de texto completo para búsquedas exhaustivas.", "Trace how wealth, neglect, group divisions, service, and equality shape communities in the Book of Mormon.": "Examina cómo la riqueza, el abandono, las divisiones, el servicio y la igualdad configuran las comunidades del Libro de Mormón.", "Compare community ideals and warnings": "Comparar ideales comunitarios y advertencias", "Communal ideal": "Ideal comunitario", "Prophetic warning": "Advertencia profética", "4 Nephi 1:3 describes shared resources and the absence of rich and poor.": "4 Nefi 1:3 describe bienes compartidos y una comunidad sin ricos ni pobres.", "Mormon 8:35–39 condemns wealth and display while vulnerable people suffer.": "Mormón 8:35–39 condena la ostentación y la riqueza mientras sufren las personas vulnerables.", "Reflect in my journal": "Reflexionar en mi diario", "Examine weakness, sorrow, repentance, grace, and growth without assuming God intends every failure, injustice, or painful experience.": "Examina debilidad, tristeza, arrepentimiento, gracia y crecimiento sin suponer que Dios quiere cada fracaso, injusticia o experiencia dolorosa.", "Distinguish the ideas": "Distinguir las ideas", "Human limitation": "Limitación humana", "Moral wrongdoing and harm": "Faltas morales y daño", "Vulnerability, incomplete knowledge, and weakness may invite humility and reliance on grace.": "La vulnerabilidad, el conocimiento incompleto y la debilidad pueden fomentar la humildad y la confianza en la gracia.", "Repentance and healing address wrongdoing and its consequences; the text does not require calling harm inherently beautiful.": "El arrepentimiento y la sanación abordan el daño y sus consecuencias; el texto no exige considerar hermoso el sufrimiento en sí.", "Save a reflection": "Guardar una reflexión", "Primary passages": "Pasajes principales", "Side-by-side comparison": "Comparación paralela", "Shared thematic context": "Contexto temático compartido", "Possible tension or distinction": "Posible tensión o diferencia", "Topic links:": "Temas relacionados:", "Representative passages": "Pasajes representativos", "Interpretive question": "Pregunta interpretativa", "Study question": "Pregunta de estudio", "Connected study path": "Ruta de estudio conectada", "Full-text search": "Búsqueda de texto completo", "Quiz": "Cuestionario", "Journal": "Diario", "Explore": "Explorar", "Finish ✓": "Terminar ✓", "Search related terms in the full text": "Buscar términos relacionados en el texto completo", "How do different authors approach": "¿Cómo abordan distintos autores", "Which passages describe experiences, and which explicitly teach principles?": "¿Qué pasajes describen experiencias y cuáles enseñan principios explícitamente?", "Start reading →": "Comenzar a leer →", "e.g., spiritual gifts, grace, motherhood, knowledge": "p. ej., dones espirituales, gracia, maternidad, conocimiento", "Enter a word or exact phrase": "Escribe una palabra o frase exacta", "Study title or scripture reference": "Título del estudio o referencia", "What did you notice? What questions do you have? What might this mean in your life?": "¿Qué observaste? ¿Qué preguntas tienes? ¿Qué significa esto en tu vida?", "Write your reflection here; save it to your journal to keep it.": "Escribe tu reflexión y guárdala en el diario.", "Your notes on this study stop...": "Tus notas sobre esta etapa...", "✦ Book of Mormon DeepDive": "✦ Libro de Mormón DeepDive", "Book of Mormon DeepDive": "Libro de Mormón DeepDive", "Change appearance": "Cambiar apariencia", "Toggle language": "Cambiar idioma", "Drag to explore · Pinch or use + / − to zoom": "Arrastra para explorar · Pellizca o usa + / − para ampliar", "Explore the connections": "Explora las conexiones", "⛶ Full screen": "⛶ Pantalla completa", "Full screen": "Pantalla completa", "⤢ Exit full screen": "⤢ Salir de pantalla completa", "← Previous": "← Anterior", "Delete": "Eliminar", "Delete this note?": "¿Eliminar esta nota?", "No notes saved yet.": "Todavía no hay notas guardadas.", "Untitled reflection": "Reflexión sin título", "Write a title or reflection first.": "Primero escribe un título o una reflexión.", "Write and save one reflection at a time.": "Escribe y guarda una reflexión a la vez.", "Invalid journal file": "Archivo de diario no válido", "Reflection": "Reflexión", "Read:": "Leer:", "Read in context ↗": "Leer en contexto ↗", "Search the full text": "Buscar en el texto completo", "Search this phrase in the full text": "Buscar esta frase en el texto completo", "Search could not initialize in this browser:": "La búsqueda no pudo iniciarse en este navegador:", "Search is still loading or unavailable.": "La búsqueda todavía se está cargando o no está disponible.", "Browser does not support DecompressionStream": "El navegador no admite DecompressionStream", "No matching pages. Try a shorter term, alternate spelling, or a related word.": "No hay páginas que coincidan. Prueba un término más corto, otra ortografía o una palabra relacionada.", "Interactive scripture constellation": "Constelación interactiva de las escrituras", "Celestial connection map": "Mapa celeste de conexiones", "Connected constellations": "Constelaciones relacionadas", "Selected topics": "Temas seleccionados", "Study path": "Ruta de estudio", "Your study flow": "Tu flujo de estudio", "My DeepDive path:": "Mi ruta de DeepDive:", "Next: connections and reflection": "Siguiente: conexiones y reflexión", "Study path complete. You can revisit any stop or build another journey.": "Ruta de estudio completada. Puedes volver a cualquier etapa o crear otro recorrido.", "Correct! Open the passage and explore why it fits.": "¡Correcto! Abre el pasaje y explora por qué encaja.", "Contextual study": "Estudio contextual", "Compare passages and explore difficult questions": "Compara pasajes y explora preguntas difíciles", "Compare this passage with other references and distinguish direct teaching from interpretation.": "Compara este pasaje con otras referencias y distingue la enseñanza directa de la interpretación.", "Explore a second topic and compare its scriptures with this one.": "Explora un segundo tema y compara sus escrituras con las de este.", "Read the verses with attention to the speaker, audience, and surrounding story.": "Lee los versículos prestando atención a quién habla, a quién se dirige y al relato que los rodea.", "What does this passage actually say, and how does its context shape your interpretation?": "¿Qué dice realmente este pasaje y cómo influye su contexto en tu interpretación?", "What stands out?": "¿Qué te llama la atención?", "What would it mean to build a community without neglect, prejudice, or class contempt?": "¿Qué significaría edificar una comunidad sin abandono, prejuicios ni desprecio de clase?", "Zion and social justice reflection": "Reflexión sobre Sion y la justicia social", "Theology of imperfection reflection": "Reflexión sobre la teología de la imperfección", "Choose a doctrine, explore its constellation, then read the connection notes below.": "Elige una doctrina, explora su constelación y lee las conexiones debajo.", "Choose a prophetic voice, then explore its passages and language patterns.": "Elige una voz profética y explora sus pasajes y patrones lingüísticos.", "Choose a theme about human limitation, then read its context and questions.": "Elige un tema sobre las limitaciones humanas y lee su contexto y preguntas.", "Choose a topic and perspective first. Open comparisons and questions only when needed.": "Primero elige un tema y una perspectiva. Abre las comparaciones y preguntas cuando las necesites.", "Choose a topic, then answer one question at a time.": "Elige un tema y responde una pregunta a la vez.", "Follow one stage at a time.": "Sigue una etapa a la vez.", "Search first, then examine results in their scriptural context.": "Primero busca y luego examina los resultados en su contexto.", "Select a social theme to examine its scripture, interpretation, and reflection.": "Selecciona un tema social para estudiar su escritura, interpretación y reflexión.", "Select topics → Build a route → Read each stop → Save your reflections.": "Selecciona temas → Crea una ruta → Lee cada etapa → Guarda tus reflexiones.", "1 · Choose a topic → 2 · Read the passages → 3 · Reflect": "1 · Elige un tema → 2 · Lee los pasajes → 3 · Reflexiona", "VERSION 10 · GRACE & HUMAN LIMITATION": "VERSIÓN 10 · GRACIA Y LIMITACIÓN HUMANA", "VERSION 10 · LANGUAGE & NARRATIVE": "VERSIÓN 10 · LENGUAJE Y NARRACIÓN", "VERSION 10 · MULTI-LENS RESEARCH": "VERSIÓN 10 · INVESTIGACIÓN CON VARIOS ENFOQUES", "VERSION 10 · SOCIAL ETHICS": "VERSIÓN 10 · ÉTICA SOCIAL", "✦ Personal revelation & grace": "✦ Revelación personal y gracia", "✦ The social gospel": "✦ El evangelio social", "The Social Gospel of the Book of Mormon": "El evangelio social del Libro de Mormón", "Five connected stops exploring poverty, prejudice, equality, and covenant responsibility.": "Cinco etapas conectadas que exploran la pobreza, los prejuicios, la igualdad y la responsabilidad del convenio.", "Six connected stops exploring revelation, weakness, grace, and growth.": "Seis etapas conectadas que exploran la revelación, la debilidad, la gracia y el crecimiento.", "Begin by reading the first set of passages in context.": "Comienza leyendo el primer grupo de pasajes en su contexto.", "Compare the questions and references across these two topics.": "Compara las preguntas y referencias de estos dos temas.", "This is a custom topic. Search the full text to discover passages that mention it.": "Este es un tema personalizado. Busca en el texto completo para descubrir pasajes que lo mencionen.", "0 selected": "0 seleccionados", "Theological distinction": "Distinción teológica", "Theological interpretation": "Interpretación teológica", "Ethical and social implications": "Implicaciones éticas y sociales", "Study lens: interpretive guidance, not a claim of historical verification.": "Enfoque de estudio: orientación interpretativa, no una afirmación de verificación histórica.", "A literary voice profile, not a quantitative authorship or linguistic attribution test.": "Perfil literario de una voz, no una prueba cuantitativa de autoría ni de atribución lingüística.", "Read these passages for a recurring theme. Related vocabulary and imagery may differ across contexts.": "Lee estos pasajes buscando un tema recurrente. El vocabulario y las imágenes relacionadas pueden variar según el contexto.", "These are thematic stops, not a chronological history of every Book of Mormon society.": "Son etapas temáticas, no una historia cronológica de cada sociedad del Libro de Mormón.", "This comparison identifies curated tags, not automated textual agreement or contradiction.": "Esta comparación identifica etiquetas seleccionadas, no coincidencias ni contradicciones textuales detectadas automáticamente.", "No shared curated topic tag; compare their ideas directly.": "No comparten ninguna etiqueta temática; compara sus ideas directamente.", "The passages belong to different narrative situations. Compare the speaker, audience, and purpose before treating their wording as directly equivalent.": "Los pasajes pertenecen a situaciones narrativas distintas. Compara quién habla, a quién se dirige y con qué propósito antes de considerar equivalentes sus palabras.", "Identify who is speaking, the intended audience, the setting, and the surrounding narrative. Compare what the passages state directly with the claims readers infer from them.": "Identifica quién habla, a qué público se dirige, el escenario y la narración que rodea el pasaje. Compara lo que los pasajes afirman directamente con lo que los lectores deducen de ellos.", "This tool uses the scriptural narrative and does not independently establish ancient historical events. Ask what social institutions, customs, and assumptions appear within the narrated world, and distinguish those from external historical evidence.": "Esta herramienta se basa en la narración de las escrituras y no establece de forma independiente acontecimientos históricos antiguos. Pregúntate qué instituciones sociales, costumbres y suposiciones aparecen en el mundo narrado, y distínguelas de la evidencia histórica externa.", "Ask who benefits, who is vulnerable, what obligations the teaching creates, and how a modern application may differ from the narrated setting. Consider difficult passages critically.": "Pregúntate quién se beneficia, quién es vulnerable, qué obligaciones crea la enseñanza y en qué puede diferir una aplicación moderna del contexto narrado. Considera con sentido crítico los pasajes difíciles.", "Which part of the passage challenges your assumptions? What response would demonstrate care for yourself and others? Avoid treating private impressions as universal requirements.": "¿Qué parte del pasaje cuestiona tus suposiciones? ¿Qué respuesta demostraría cuidado por ti y por los demás? Evita convertir impresiones personales en requisitos universales.", "The text does not supply a complete modern economic policy. Explore the moral principles and compare how different communities distribute resources and dignity. Consider how this relates to Christ, covenant responsibility, revelation, and grace without treating one interpretation as the only possible reading.": "El texto no ofrece una política económica moderna completa. Explora los principios morales y compara cómo distintas comunidades distribuyen los recursos y la dignidad. Considera cómo se relaciona esto con Cristo, la responsabilidad del convenio, la revelación y la gracia, sin tratar una interpretación como la única lectura posible.", "Compare Nephi’s lament in 2 Nephi 4 with Alma’s account in Alma 36. How do struggle and repentance differ from the idea that wrongdoing itself is divinely intended?": "Compara el lamento de Nefi en 2 Nefi 4 con el relato de Alma en Alma 36. ¿En qué se diferencian la lucha y el arrepentimiento de la idea de que Dios quiere el pecado mismo?", "Compare prayer, a softened heart, a still voice, testimony, and the Holy Ghost. What makes each account distinctive, and what do they share?": "Compara la oración, el corazón ablandado, la voz apacible, el testimonio y el Espíritu Santo. ¿Qué hace singular cada relato y qué tienen en común?", "How do Jacob 3 and 4 Nephi complicate inherited prejudices and labels?": "¿Cómo cuestionan Jacob 3 y 4 Nefi los prejuicios y las etiquetas heredadas?", "How do weakness, grace, repentance, and healing differ in the passages I studied?": "¿En qué se diferencian la debilidad, la gracia, el arrepentimiento y la sanación en los pasajes que estudié?", "How does King Benjamin challenge the tendency to blame people for their poverty?": "¿Cómo cuestiona el rey Benjamín la tendencia a culpar a las personas de su pobreza?", "How does Mormon 8 connect wealth, religious appearance, and indifference to suffering?": "¿Cómo relaciona Mormón 8 la riqueza, la apariencia religiosa y la indiferencia ante el sufrimiento?", "How might you recognize a personal pattern in your own spiritual experiences without assuming everyone experiences the Spirit in the same way?": "¿Cómo podrías reconocer un patrón personal en tus propias experiencias espirituales sin suponer que todos sienten el Espíritu de la misma manera?", "How should readers handle passages that describe skin color and group identity alongside 2 Nephi 26:33?": "¿Cómo deben leerse los pasajes que describen el color de la piel y la identidad de grupo junto con 2 Nefi 26:33?", "What differences exist between sharing voluntarily and creating durable communal obligations?": "¿Qué diferencias hay entre compartir voluntariamente y crear obligaciones comunitarias duraderas?", "What does 4 Nephi mean when it says there were no rich and poor?": "¿Qué quiere decir 4 Nefi cuando afirma que no había ricos ni pobres?", "What might it mean to be loved and invited to grow while still imperfect? How does Christ’s healing in Alma 7:11–13 shape your answer?": "¿Qué podría significar ser amado e invitado a crecer aun siendo imperfecto? ¿Cómo influye en tu respuesta la sanación de Cristo en Alma 7:11–13?", "What obligations arise from baptismal promises and shared material dependence?": "¿Qué obligaciones surgen de las promesas bautismales y de la dependencia material compartida?", "Which forms of neglect are individual, and which are embedded in social practices?": "¿Qué formas de abandono son individuales y cuáles están arraigadas en prácticas sociales?", "The phrase “spiritual idiolect” is a modern interpretive metaphor, not a term used in the Book of Mormon. How do Nephi, Enos, Alma, and the people at Bountiful each describe receiving divine communication?": "La expresión «idiolecto espiritual» es una metáfora interpretativa moderna, no un término del Libro de Mormón. ¿Cómo describen Nefi, Enós, Alma y el pueblo en Abundancia la manera en que recibieron comunicación divina?", "“The divine beauty of imperfection” is a study lens, not a direct scriptural phrase. In Ether 12:27, how are weakness, humility, grace, and strength connected?": "«La belleza divina de la imperfección» es un enfoque de estudio, no una frase de las escrituras. En Éter 12:27, ¿cómo se relacionan la debilidad, la humildad, la gracia y la fortaleza?", "voice and hearing": "voz y escucha", "weakness and strength": "debilidad y fortaleza", "rich and poor": "ricos y pobres", "all are alike": "todos son iguales", "heart and change": "corazón y cambio", "remembering": "recordar", "Alma explores the relationship between justice, mercy, repentance, and redemption.": "Alma explora la relación entre justicia, misericordia, arrepentimiento y redención.", "After teaching dependence on God, Benjamin turns to the obligation to assist people who ask for help and cautions against judging them.": "Después de enseñar que dependemos de Dios, Benjamín pasa a la obligación de ayudar a quienes piden ayuda y advierte contra juzgarlos.", "Alma asks his listeners how he knows the teachings he has declared, pointing to fasting, prayer, and the Holy Spirit.": "Alma pregunta a sus oyentes cómo sabe lo que ha declarado y señala el ayuno, la oración y el Espíritu Santo.", "Alma describes baptismal willingness in concrete social terms: bearing burdens, mourning, comforting, and witnessing.": "Alma describe la disposición bautismal en términos sociales concretos: llevar cargas, llorar con otros, consolar y testificar.", "Alma recounts anguish over his past and the transformative moment of remembering Jesus Christ.": "Alma relata su angustia por el pasado y el momento transformador en que recuerda a Jesucristo.", "Covenant identity here has public, communal implications; baptism is not only an inward commitment.": "Aquí la identidad del convenio tiene implicaciones públicas y comunitarias; el bautismo no es solo un compromiso interior.", "Economic equality is depicted as part of a broader social transformation after Christ's ministry, alongside unity and the absence of contention.": "La igualdad económica aparece como parte de una transformación social más amplia tras el ministerio de Cristo, junto con la unidad y la ausencia de contención.", "Enos remembers his father's teaching, prays intensely, receives assurance, and begins to plead for others.": "Enós recuerda las enseñanzas de su padre, ora intensamente, recibe seguridad y comienza a suplicar por otras personas.", "His account emphasizes an extended process of seeking. Compare it with more sudden experiences elsewhere in the record.": "Su relato destaca un proceso prolongado de búsqueda. Compáralo con experiencias más repentinas en otras partes del registro.", "His spiritual language is narrated through hunger, wrestling, forgiveness, and widening concern rather than a single sensation.": "Su lenguaje espiritual se narra mediante el hambre, la lucha, el perdón y una preocupación cada vez más amplia, no mediante una única sensación.", "His testimony centers grace and change, without implying that wrongdoing itself was a divine requirement.": "Su testimonio se centra en la gracia y el cambio, sin dar a entender que el pecado mismo fuera un requisito divino.", "How can prosperity distort the values a community professes?": "¿Cómo puede la prosperidad distorsionar los valores que una comunidad profesa?", "How does Enos's prayer change its focus?": "¿Cómo cambia el enfoque de la oración de Enós?", "How does Nephi's response differ from the responses of his brothers?": "¿En qué se diferencia la respuesta de Nefi de la de sus hermanos?", "How does the order of seeking God and seeking riches affect the teaching?": "¿Cómo afecta a la enseñanza el orden entre buscar a Dios y buscar riquezas?", "How does the surrounding exchange about writing change the way you read the verse?": "¿Cómo cambia tu lectura del versículo el diálogo sobre la escritura que lo rodea?", "How does the teaching respond to the claim that someone has brought poverty upon themselves?": "¿Cómo responde la enseñanza a la afirmación de que alguien se ha buscado su propia pobreza?", "How does this verse challenge status, gender, ethnic, or social boundaries?": "¿Cómo cuestiona este versículo las fronteras de estatus, género, etnia o clase social?", "How might shared resources and shared belonging reinforce each other?": "¿Cómo podrían reforzarse mutuamente los recursos compartidos y la pertenencia compartida?", "Jacob tells his audience to seek God's kingdom first and to use wealth to clothe, feed, and liberate others.": "Jacob pide a su pueblo que busque primero el reino de Dios y que use la riqueza para vestir, alimentar y liberar a otros.", "Jacob turns criticism toward his own community and praises the familial faithfulness of people his audience has disparaged.": "Jacob dirige la crítica hacia su propia comunidad y elogia la fidelidad familiar de un pueblo que sus oyentes habían despreciado.", "Members of the church share material resources and care for those in need without regard to social status.": "Los miembros de la iglesia comparten sus recursos materiales y cuidan de los necesitados sin importar su posición social.", "Moroni addresses future readers and condemns outward religious display and wealth while the needy suffer.": "Moroni se dirige a lectores futuros y condena la ostentación religiosa y la riqueza mientras sufren los necesitados.", "Moroni writes after expressing anxiety about weakness in writing. The reply redirects attention from rhetorical perfection to humility and grace.": "Moroni escribe después de expresar su inquietud por su debilidad al escribir. La respuesta desvía la atención de la perfección retórica hacia la humildad y la gracia.", "Nephi concludes an invitation to come to Christ with an explicit statement of universal divine welcome.": "Nefi concluye una invitación a venir a Cristo con una declaración explícita de la acogida universal de Dios.", "Nephi recounts seeking the Lord during his family's difficult departure. He describes a softened heart and then speaks to Sam.": "Nefi relata cómo buscó al Señor durante la difícil partida de su familia. Describe un corazón ablandado y luego habla con Sam.", "Nephi's account of separation includes troubling language associating a curse and a skin description.": "El relato de Nefi sobre la separación incluye un lenguaje inquietante que asocia una maldición con una descripción de la piel.", "Nephi's personal lament follows family blessings and the death of Lehi. He moves between grief, memory of divine help, and renewed trust.": "El lamento personal de Nefi sigue a las bendiciones familiares y a la muerte de Lehi. Pasa del dolor al recuerdo de la ayuda divina y a una confianza renovada.", "Read this as a difficult textual claim within a partisan narrative, not a scientific explanation of race or permission for discrimination. Compare 2 Nephi 26:33 and Jacob 3.": "Léelo como una afirmación textual difícil dentro de una narración parcial, no como una explicación científica de la raza ni como un permiso para discriminar. Compáralo con 2 Nefi 26:33 y Jacob 3.", "Revelation here involves attention and recognition over time. A modern spiritual-idiolect reading may compare this with other accounts without claiming one universal mechanism.": "Aquí la revelación implica atención y reconocimiento con el tiempo. Una lectura moderna desde el idiolecto espiritual puede compararla con otros relatos sin afirmar un mecanismo universal.", "The assembled people hear a voice three times before understanding it, then turn their attention toward heaven.": "El pueblo reunido oye una voz tres veces antes de entenderla y luego dirige su atención hacia el cielo.", "The critique turns inward toward the believing community, not merely toward outsiders.": "La crítica se dirige hacia la propia comunidad creyente, no solo hacia los de fuera.", "The experience joins inward change with communication to another person, suggesting that personal revelation can have relational consequences.": "La experiencia une el cambio interior con la comunicación a otra persona, lo que sugiere que la revelación personal puede tener consecuencias en las relaciones.", "The logic links divine mercy to economic conduct: people who receive compassion must not withhold it from others.": "El razonamiento relaciona la misericordia divina con la conducta económica: quienes reciben compasión no deben negársela a los demás.", "The narrator describes a society sharing possessions and goods, with no rich and poor among them.": "El narrador describe una sociedad que comparte posesiones y bienes, sin ricos ni pobres entre ellos.", "The narrator links wealth, costly apparel, pride, and inequality with spiritual decline among church members.": "El narrador relaciona la riqueza, la ropa costosa, el orgullo y la desigualdad con el declive espiritual de los miembros de la iglesia.", "The passage allows sorrow and discipleship to coexist. Spiritual maturity need not require pretending to be emotionally flawless.": "El pasaje permite que la tristeza y el discipulado coexistan. La madurez espiritual no exige fingir una perfección emocional.", "The passage makes equality visible through recurring practice rather than only an ideal or feeling.": "El pasaje hace visible la igualdad mediante una práctica constante, no solo como ideal o sentimiento.", "The passage shifts the moral purpose of prosperity from status acquisition toward responsibility for neighbors.": "El pasaje desplaza el propósito moral de la prosperidad de la búsqueda de estatus hacia la responsabilidad por el prójimo.", "The passage unsettles easy assumptions that the narrator's own group is morally superior. It is valuable when examining prejudice within scripture.": "El pasaje desestabiliza la suposición fácil de que el grupo del narrador es moralmente superior. Es valioso para examinar los prejuicios dentro de las escrituras.", "The verse provides a strong standard against exclusion, even as readers wrestle with difficult group descriptions elsewhere in the book.": "El versículo ofrece una norma firme contra la exclusión, aunque los lectores luchen con descripciones difíciles de grupos en otras partes del libro.", "The warning is about priorities, systems of esteem, and neglected people—not simply about personal generosity.": "La advertencia trata de prioridades, sistemas de estima y personas desatendidas, no solo de la generosidad personal.", "Weakness is not celebrated as harm; it becomes an occasion for dependence on Christ. The promise of strength is relational, not a claim that all difficulties disappear.": "La debilidad no se celebra como un daño; se convierte en una ocasión para depender de Cristo. La promesa de fortaleza es relacional, no una afirmación de que todas las dificultades desaparecerán.", "What changes between Nephi's initial lament and his final prayer?": "¿Qué cambia entre el lamento inicial de Nefi y su oración final?", "What changes when the narrator's perspective and later counterpoints are considered?": "¿Qué cambia cuando se tienen en cuenta la perspectiva del narrador y los contrapuntos posteriores?", "What does Alma remember before his emotional turning point?": "¿Qué recuerda Alma antes de su momento decisivo?", "What does the repetition accomplish in the narrative?": "¿Qué logra la repetición en la narración?", "What habits would be needed to sustain this pattern?": "¿Qué hábitos se necesitarían para sostener este patrón?", "What is the relationship between study, prayer, and witness?": "¿Qué relación hay entre el estudio, la oración y el testimonio?", "What would bearing another person's burden look like materially?": "¿Cómo sería, en lo material, llevar la carga de otra persona?", "Which forms of religious success might conceal injustice?": "¿Qué formas de éxito religioso podrían ocultar la injusticia?", "Whose conduct is being corrected, and whose conduct is praised?": "¿La conducta de quién se corrige y la de quién se elogia?", "Study commentary · Interpretations are distinct from scripture text. Open references below to examine the passages.": "Comentario de estudio · Las interpretaciones son distintas del texto de las escrituras. Abre las referencias de abajo para examinar los pasajes.", "Nephi": "Nefi", "Mormon": "Mormón", "Spirit": "Espíritu"};
const TOPICS_ES={"Faith": "Fe", "Jesus Christ": "Jesucristo", "Grace and Atonement": "Gracia y Expiación", "Prayer": "Oración", "Holy Ghost": "Espíritu Santo", "Covenants": "Convenios", "Repentance": "Arrepentimiento", "Forgiveness": "Perdón", "Charity and Love": "Caridad y amor", "Agency": "Albedrío", "Justice and Mercy": "Justicia y misericordia", "Revelation": "Revelación", "Identity and Divine Potential": "Identidad y potencial divino", "Women in the Book of Mormon": "Las mujeres en el Libro de Mormón", "Leadership": "Liderazgo", "War and Peace": "Guerra y paz", "Pride and Humility": "Orgullo y humildad", "Baptism": "Bautismo", "Resurrection": "Resurrección", "Family": "Familia", "Spiritual Language & Idiolects": "Lenguaje espiritual e idiolectos", "The Divine Beauty of Imperfection": "La belleza divina de la imperfección", "Caring for the Poor": "Cuidar de los pobres", "Neglecting the Poor": "Desatender a los pobres", "Racism and Prejudice": "Racismo y prejuicios", "Economic Equality": "Igualdad económica"};
const REV={};for(const k in D)if(!(D[k] in REV))REV[D[k]]=k;
const isEs=()=>{try{return localStorage.getItem('deepdive-language')==='es'}catch(e){return false}};
const topic=t=>TOPICS_ES[t]||D[t]||t;
const isTopicList=s=>s.includes(', ')&&s.split(', ').every(p=>p in TOPICS_ES);
const PATTERNS=[
 [/^(\d+) selected$/,m=>m[1]+(m[1]==='1'?' seleccionado':' seleccionados')],
 [/^(\d+)% through your path$/,m=>'Has completado el '+m[1]+' % de tu ruta'],
 [/^Stop (\d+) of (\d+)$/,m=>'Etapa '+m[1]+' de '+m[2]],
 [/^STOP (\d+) OF (\d+)$/,m=>'ETAPA '+m[1]+' DE '+m[2]],
 [/^Next: (.+) →$/,m=>'Siguiente: '+topic(m[1])+' →'],
 [/^How do different authors approach (.+)\? What remains consistent across their accounts\?$/,m=>'¿Cómo abordan distintos autores el tema «'+topic(m[1])+'»? ¿Qué se mantiene constante en sus relatos?'],
 [/^Which passage is one of the suggested starting points for studying “(.+)”\?$/,m=>'¿Qué pasaje es uno de los puntos de partida sugeridos para estudiar «'+topic(m[1])+'»?'],
 [/^Not this time\. Suggested answer: (.+)$/,m=>'Esta vez no. Respuesta sugerida: '+m[1]],
 [/^Open original PDF at page (\d+) ↗$/,m=>'Abrir el PDF original en la página '+m[1]+' ↗'],
 [/^PDF page (\d+)$/,m=>'Página '+m[1]+' del PDF'],
 [/^• (\d+) keyword occurrences?$/,m=>'• '+m[1]+(m[1]==='1'?' aparición':' apariciones')+' de la palabra clave'],
 [/^(\d+) matching PDF pages • showing first (\d+), ranked by term frequency$/,m=>m[1]+' páginas del PDF coinciden • se muestran las primeras '+m[2]+', ordenadas por frecuencia del término'],
 [/^Ready: (\d+) searchable scripture pages available offline\.$/,m=>'Listo: '+m[1]+' páginas de las escrituras disponibles para buscar sin conexión.'],
 [/^Search could not initialize in this browser: (.*)$/,m=>'La búsqueda no pudo iniciarse en este navegador: '+m[1]],
 [/^Connections radiating from (.+)$/,m=>'Conexiones que parten de '+topic(m[1])],
 [/^Study (.+)$/,m=>(m[1] in TOPICS_ES)?'Estudiar '+topic(m[1]):null],
 [/^([\s\S]+) Consider how this relates to Christ, covenant responsibility, revelation, and grace without treating one interpretation as the only possible reading\.$/,m=>(tr(m[1])||m[1])+' Considera cómo se relaciona esto con Cristo, la responsabilidad del convenio, la revelación y la gracia, sin tratar una interpretación como la única lectura posible.'],
 [/^(.+) ↗$/,m=>{const t=tr(m[1]);return t?t+' ↗':null}],
];
function tr(s){
 if(!s)return null;
 if(D[s])return D[s];
 const n=s.replace(/\s+/g,' ');if(D[n])return D[n];
 if(TOPICS_ES[s]&&TOPICS_ES[s]!==s)return TOPICS_ES[s];
 if(isTopicList(s))return s.split(', ').map(topic).join(', ');
 for(const [re,fn] of PATTERNS){const m=s.match(re);if(m){const r=fn(m);if(r&&r!==s)return r}}
 return null;
}
window.deepDiveTranslate=s=>isEs()?(tr(s)||s):s;
const textMemo=new WeakMap(),attrMemo=new WeakMap();
const ATTRS=['placeholder','aria-label','title'];
function skip(el){return !el||el.closest('script,style,textarea,[contenteditable],.result p')}
function fixOptions(){document.querySelectorAll('select option').forEach(o=>{if(!o.hasAttribute('value')){const t=o.textContent.trim();o.setAttribute('value',REV[t]||t)}})}
let busy=false;
function apply(){
 if(busy)return;busy=true;
 try{
  fixOptions();
  const es=isEs();
  const w=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let n;
  while(n=w.nextNode()){
   if(skip(n.parentElement))continue;
   const raw=n.nodeValue,trim=raw.trim();if(!trim)continue;
   if(es){const t=tr(trim);if(t&&t!==trim){n.nodeValue=raw.replace(trim,t);textMemo.set(n,{en:raw,es:n.nodeValue})}}
   else{const m=textMemo.get(n);if(m&&n.nodeValue===m.es)n.nodeValue=m.en;else if(REV[trim]&&!m){/* leave other scripts' text alone */}}
  }
  document.querySelectorAll('[placeholder],[aria-label],[title]').forEach(el=>{
   let memo=attrMemo.get(el);
   for(const a of ATTRS){const v=el.getAttribute(a);if(!v)continue;
    if(es){const t=tr(v);if(t&&t!==v){el.setAttribute(a,t);if(!memo){memo={};attrMemo.set(el,memo)}memo[a]={en:v,es:t}}}
    else if(memo&&memo[a]&&v===memo[a].es)el.setAttribute(a,memo[a].en)}
  });
  document.title=es?'Libro de Mormón DeepDive':'Book of Mormon DeepDive';
 }finally{busy=false}
}
let pending=0;
function schedule(){if(pending)return;pending=setTimeout(()=>{pending=0;apply()},60)}
new MutationObserver(schedule).observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:ATTRS});
document.getElementById('v12Language')?.addEventListener('click',()=>{setTimeout(apply,0);setTimeout(apply,200);setTimeout(apply,500)});
const oAlert=window.alert.bind(window),oConfirm=window.confirm.bind(window);
window.alert=m=>oAlert(window.deepDiveTranslate(String(m)));
window.confirm=m=>oConfirm(window.deepDiveTranslate(String(m)));
apply();
})();
